async function resolveTarget(
  paseo: PaseoApi,
  settings: ContinuitySettings,
  state: ContinuityState,
  agent: FailedAgent,
  forcedProvider?: string,
): Promise<ResolvedTarget | null> {
  const snapshot = await paseo.providers.snapshot({ cwd: agent.cwd }).catch((error: unknown) => {
    log("provider snapshot failed", errorText(error));
    return null;
  });
  const entries = new Map((snapshot?.entries ?? []).map((entry) => [entry.provider, entry]));
  const rejected = new Set<string>();

  for (;;) {
    const forcedId = forcedProvider ? providerIdOf(forcedProvider) : null;
    const entry = pickNextEntry({
      currentProvider: agent.provider,
      chain: forcedId
        ? [
            settings.chain.find((candidate) => providerIdOf(candidate.provider) === forcedId) ?? {
              provider: forcedId,
              model: null,
              modeId: null,
              thinkingOptionId: null,
            },
          ]
        : settings.chain,
      isCoolingDown: (provider) => !forcedId && state.isCoolingDown(provider),
      isAvailable: (provider) => {
        if (rejected.has(provider)) return false;
        const info = entries.get(provider);
        // Without a snapshot we cannot tell; let creation fail visibly instead.
        return snapshot === null || (info !== undefined && info.enabled !== false && info.status === "ready");
      },
    });
    if (!entry) {
      return null;
    }
    const provider = providerIdOf(entry.provider);
    const info = entries.get(provider);
    const models = info?.models?.filter((model) => model.isSelectable !== false) ?? [];
    const model =
      entry.model ?? models.find((candidate) => candidate.isDefault)?.id ?? models[0]?.id ?? null;
    if (!model) {
      log("no model for fallback provider", provider);
      rejected.add(provider);
      continue;
    }
    const modes = info?.modes ?? [];
    const modeId =
      entry.modeId && (modes.length === 0 || modes.some((mode) => mode.id === entry.modeId))
        ? entry.modeId
        : (info?.defaultModeId ?? undefined);
    return {
      entry,
      provider,
      model,
      modeId: modeId ?? undefined,
      thinkingOptionId: entry.thinkingOptionId ?? undefined,
    };
  }
}

/** Final assistant text is only trusted when it is a short status line, not a discussion. */
const MAX_ASSISTANT_EVIDENCE_CHARS = 400;

export function classifyTurn(
  outcome: PluginTurnOutcome,
  timeline: readonly AgentTimelineItem[],
  triggers: ContinuitySettings["triggers"],
  now: number = Date.now(),
): Classification | null {
  if (outcome.kind === "canceled") {
    return null;
  }

  const evidence: string[] = [];
  if (outcome.kind === "failed") {
    evidence.push([outcome.error.code, outcome.error.message].filter(Boolean).join(": "));
  }

  const turn = latestTurnItems(timeline);
  for (const item of turn) {
    if (item.type === "error") {
      evidence.push(item.message);
    } else if (item.type === "notification" && item.level !== "info") {
      evidence.push(item.message);
    }
  }

  const assistant = lastAssistantText(turn);
  if (assistant && assistant.length <= MAX_ASSISTANT_EVIDENCE_CHARS) {
    evidence.push(assistant);
  }

  const ordered: Array<[Classification["class"], RegExp[], boolean]> = [
    ["quota", QUOTA, triggers.quota],
    ["rate_limit", RATE_LIMIT, triggers.rateLimit],
    ["overloaded", OVERLOADED, triggers.overloaded],
  ];

  for (const text of evidence) {
    for (const [failureClass, patterns, enabled] of ordered) {
      if (!enabled || !patterns.some((pattern) => pattern.test(text))) {
        continue;
      }
      const resetAt = parseResetAt(text, now);
      return {
        class: failureClass,
        evidence: compact(text, 300),
        ...(resetAt === undefined ? {} : { resetAt }),
      };
    }
  }
  return null;
}

/** Best-effort parse of "resets at 3pm", "|1759300000", or "try again in 20 minutes". */
export function parseResetAt(text: string, now: number): number | undefined {
  const epoch = text.match(/\|(\d{10,13})\b/);
  if (epoch) {
    const value = Number(epoch[1]);
    const millis = value < 1e12 ? value * 1000 : value;
    if (millis > now) {
      return millis;
    }
  }

  const relative = text.match(
    /(?:try again|retry|resets?) in (\d+(?:\.\d+)?)\s*(s|sec|seconds?|m|min|minutes?|h|hr|hours?)\b/i,
  );

